    {"offset": {"line": 4, "column": 0}, "map": {"version":3,"sources":["file:///D:/doanchuyennganha/client/src/app/%28user%29/components/Filters.jsx"],"sourcesContent":["\"use client\";\r\nimport React from \"react\";\r\n\r\nconst Filters = ({\r\n  priceRange,\r\n  color,\r\n  material,\r\n  sortBy,\r\n  onPriceRangeChange,\r\n  onColorChange,\r\n  onMaterialChange,\r\n  onSortChange,\r\n}) => {\r\n  return (\r\n    <div className=\" flex flex-col gap-[11px]\">\r\n      <p className=\"text-[24px]\">Bộ lọc</p>\r\n      <div\r\n        className=\"flex flex-col gap-2 ml-[20px] text-[15px]\"\r\n        style={{ accentColor: \"black\" }}\r\n      >\r\n        {/* loc theo gia tien */}\r\n        <p className=\"text-[20px]\">Theo giá</p>\r\n        <label className=\"flex items-center cursor-pointer\">\r\n          <input\r\n            type=\"checkbox\"\r\n            name=\"priceGroup\"\r\n            value=\"1\"\r\n            checked={priceRange === \"1\"}\r\n            onChange={(e) =>\r\n              onPriceRangeChange?.(e.target.checked ? e.target.value : \"\")\r\n            }\r\n            className=\"mr-2 cursor-pointer\"\r\n          />\r\n          <p>Dưới 20 triệu</p>\r\n        </label>\r\n        <label className=\"flex items-center cursor-pointer\">\r\n          <input\r\n            type=\"checkbox\"\r\n            name=\"priceGroup\"\r\n            value=\"2\"\r\n            checked={priceRange === \"2\"}\r\n            onChange={(e) =>\r\n              onPriceRangeChange?.(e.target.checked ? e.target.value : \"\")\r\n            }\r\n            className=\"mr-2 cursor-pointer\"\r\n          />\r\n          <p>Từ 20 triệu đến 30 triệu</p>\r\n        </label>\r\n        <label className=\"flex items-center cursor-pointer\">\r\n          <input\r\n            type=\"checkbox\"\r\n            name=\"priceGroup\"\r\n            value=\"3\"\r\n            checked={priceRange === \"3\"}\r\n            onChange={(e) =>\r\n              onPriceRangeChange?