      value=\"7\"\r\n            checked={color === \"7\"}\r\n            onChange={(e) =>\r\n              onColorChange?.(e.target.checked ? e.target.value : \"\")\r\n            }\r\n            className=\"mr-2 appearance-none w-[13] h-[13] border-2 border-[#D6D6D6] checked:bg-[#D6D6D6] cursor-pointer\"\r\n          />\r\n          <p>Trắng</p>\r\n        </label>\r\n        {/* loc theo chat lieu */}\r\n        <p className=\"text-[20px]\">Chất liệu</p>\r\n        <label className=\"flex items-center cursor-pointer\">\r\n          <input\r\n            type=\"checkbox\"\r\n            name=\"materialGroup\"\r\n            value=\"8\"\r\n            checked={material === \"8\"}\r\n            onChange={(e) =>\r\n              onMaterialChange?.(e.target.checked ? e.target.value : \"\")\r\n            }\r\n            className=\"mr-2 cursor-pointer\"\r\n          />\r\n          <p>Vàng</p>\r\n        </label>\r\n        <label className=\"flex items-center cursor-pointer\">\r\n          <input\r\n            type=\"checkbox\"\r\n            name=\"materialGroup\"\r\n            value=\"9\"\r\n            checked={material === \"9\"}\r\n            onChange={(e) =>\r\n              onMaterialChange?.(e.target.checked ? e.target.value : \"\")\r\n            }\r\n            className=\"mr-2 cursor-pointer\"\r\n          />\r\n          <p>Kim cương</p>\r\n        </label>\r\n      </div>\r\n\r\n      <p className=\"text-[24px]\">Sắp xếp</p>\r\n      <div className=\"flex flex-col gap-2\" style={{ accentColor: \"black\" }}>\r\n        <label className=\"flex items-center cursor-pointer\">\r\n          <input\r\n            type=\"checkbox\"\r\n            name=\"sortGroup\"\r\n            value=\"priceAsc\"\r\n            checked={sortBy === \"priceAsc\"}\r\n            onChange={(e) => onSortChange?.(e.target.checked ? \"priceAsc\" : \"\")}\r\n            className=\"mr-2 cursor-pointer\"\r\n          />\r\n          <p>Giá từ thấp đến cao</p>\r\n        </label>\r\n\r\n        <label className=\"flex items-center cursor-pointer\">\r\n          <input\r\n            type=\"checkbox\"\r\n            name=\"sortGroup\"\r\n            value=\"priceDesc\"\r\n            checked={sortBy === \"priceDesc\"}\r\n            onChange={(e) =>\r\n              onSortChange?.(e.target.checked ? \"priceDesc\" : \"\")\r\n            }\r\n            className=\"mr-2 cursor-pointer\"\r\n          />\r\n          <p>Giá từ cao đến thấp</p>\r\n        </label>\r\n\r\n        <label className=\"flex items-center cursor-pointer\">\r\n          <input\r\n            type=\"checkbox\"\r\n            name=\"sortGroup\"\r\n            value=\"bestSeller\"\r\n            checked={sortBy === \"bestSeller\"}\r\n            onChange={(e) =>\r\n              onSortChange?.(e.target.checked ? \"bestSeller\" : \"\")\r\n            }\r\n            className=\"mr-2 cursor-pointer\"\r\n          />\r\n          <p>Bán chạy</p>\r\n        </label>\r\n\r\n        <label className=\"flex items-center cursor-pointer\">\r\n          <input\r\n            type=\"checkbox\"\r\n            name=\"sortGroup\"\r\n            value=\"nameAsc\"\r\n            checked={sortBy === \"nameAsc\"}\r\n            onChange={(e) => onSortChange?.(e.target.checked ? \"nameAsc\" : \"\")}\r\n            className=\"mr-2 cursor-pointer\"\r\n          />\r\n          <p>A-Z</p>\r\n        </label>\r\n      </div>\r\n    </div>\r\n  );\r\n};\r\n\r\nexport default Filters;\r\n\r\n"],"names":[],"mappings":";;;;;AACA;AADA;;;AAGA,MAAM,UAAU,CAAC,EACf,UAAU,EACV,KAAK,EACL,QAAQ,EACR,MAAM,EACN,kBAAkB,EAClB,aAAa,EACb,gBAAgB,EAChB,YAAY,EACb;IACC,qBACE,8OAAC;QAAI,WAAU;;0BACb,8OAAC;gBAAE,WAAU;0BAAc;;;;;;0BAC3B,8OAAC;gBACC,WAAU;gBACV,OAAO;oBAAE,aAAa;gBAAQ;;kCAG9B,8OAAC;wBAAE,WAAU;kCAAc;;;;;;kCAC3B,8OAAC;wBAAM,WAAU;;0CACf,8OAAC;gCACC,MAAK;gCACL,MAAK;gCACL,OAAM;gCACN,SAAS,eAAe;gCACxB,UAAU,CAAC,IACT,qBAAqB,EAAE,MAAM,CAAC,OAAO,GAAG,EAAE,MAAM,CAAC,KAAK,GAAG;gCAE3D,WAAU;;;;;;0CAEZ,8OAAC;0CAAE;;;;;;;;;;