    {"offset": {"line": 457, "column": 0}, "map": {"version":3,"sources":["file:///D:/doanchuyennganha/client/src/app/%28user%29/components/ProductCard.jsx"],"sourcesContent":["\"use client\";\r\nimport React from \"react\";\r\nimport HeartIcon from \"../../../assets/icons/heart_icon\";\r\nimport { toIntegerVND } from \"../utils/price\";\r\nimport { useRouter } from \"next/navigation\";\r\n\r\nconst formatPriceVND = (input) =>\r\n  new Intl.NumberFormat(\"vi-VN\", { maximumFractionDigits: 0 }).format(\r\n    toIntegerVND(input)\r\n  );\r\n\r\nconst ProductCard = ({ item, isFavorite, onToggleFavorite }) => {\r\n  const router = useRouter();\r\n  \r\n  const goToDetail = () => {\r\n    const id = item?.product_id;\r\n    const cat = String(item?.Category?.name || \"\").trim().toLowerCase();\r\n    if (!id) return;\r\n    const map = {\r\n      \"nhan\": \"ring\",\r\n      \"bong tai\": \"earring\",\r\n      \"day chuyen\": \"necklace\",\r\n      \"vong tay\": \"bracelet\",\r\n    };\r\n    const segment = map[cat] || \"ring\";\r\n    router.push(`/${segment}/${id}`);\r\n  };\r\n\r\n  return (\r\n    <div\r\n      className=\"w-[250px] h-[350px] flex flex-col justify-around border border-[#D6D6D6] hover:shadow-xl transition-shadow duration-300 rounded-md cursor-pointer relative\"\r\n      onClick={goToDetail}\r\n    >\r\n      {item?.ProductImages?.map((img, idx) => (\r\n        <div key={idx}>{img.is_main === true && <img src={img.image_url} />}</div>\r\n      ))}\r\n      <div className=\"text-[20px] font-medium ml-[15px]\">{item?.name}</div>\r\n      <div className=\"text-[16px] text-[#C0C0C0] mt-[20px] mb-[10px] ml-[15px]\">{formatPriceVND(item?.price)}</div>\r\n      <button\r\n        type=\"button\"\r\n        aria-label=\"Yêu thích\"\r\n        className=\" absolute top-[10px] right-[10px]\"\r\n        onClick={(e) => {\r\n          e.preventDefault();\r\n          e.stopPropagation();\r\n          onToggleFavorite?.();\r\n        }}\r\n      >\r\n        <HeartIcon isFavorite={isFavorite} onClick={() => {}} />\r\n      </button>\r\n    </div>\r\n  );\r\n};\r\n\r\nexport default ProductCard;\r\n\r\n"],"names":[],"mappings":";;;;;AACA;AACA;AACA;AACA;AAJA;;;;;;AAMA,MAAM,iBAAiB,CAAC,QACtB,IAAI,KAAK,YAAY,CAAC,SAAS;QAAE,uBAAuB;IAAE,GAAG,MAAM,CACjE,IAAA,wJAAY,EAAC;AAGjB,MAAM,cAAc,CAAC,EAAE,IAAI,EAAE,UAAU,EAAE,gBAAgB,EAAE;IACzD,MAAM,SAAS,IAAA,+IAAS;IAExB,MAAM,aAAa;QACjB,MAAM,KAAK,MAAM;QACjB,MAAM,MAAM,OAAO,MAAM,UAAU,QAAQ,IAAI,IAAI,GAAG,WAAW;QACjE,IAAI,CAAC,IAAI;QACT,MAAM,MAAM;YACV,QAAQ;YACR,YAAY;YACZ,cAAc;YACd,YAAY;QACd;QACA,MAAM,UAAU,GAAG,CAAC,IAAI,IAAI;QAC5B,OAAO,IAAI,CAAC,CAAC,CAAC,EAAE,QAAQ,CAAC,EAAE,IAAI;IACjC;IAEA,qBACE,8OAAC;QACC,WAAU;QACV,SAAS;;YAER,MAAM,eAAe,IAAI,CAAC,KAAK,oBAC9B,8OAAC;8BAAe,IAAI,OAAO,KAAK,sBAAQ,8OAAC;wBAAI,KAAK,IAAI,SAAS;;;;;;mBAArD;;;;;0BAEZ,8OAAC;gBAAI,WAAU;0BAAqC,MAAM;;;;;;0BAC1D,8OAAC;gBAAI,WAAU;0BAA4D,eAAe,MAAM;;;;;;0BAChG,8OAAC;gBACC,MAAK;gBACL,cAAW;gBACX,WAAU;gBACV,SAAS,CAAC;oBACR,EAAE,cAAc;oBAChB,EAAE,eAAe;oBACjB;gBACF;0BAEA,cAAA,8OAAC,+IAAS;oBAAC,YAAY;oBAAY,SAAS,KAAO;;;;;;;;;;;;;;;;;AAI3D;uCAEe","debugId":null}},
    {"offset": {"line": 557, "column": 0}, "map": {"version":3,"sources":["file:///D:/doanchuyennganha/client/src/app/%28user%29/components/ProductGrid.jsx"],"sourcesContent":["\"use client\";\r\nimport React from \"react\";\r\nimport ProductCard from \"./ProductCard\";\r\n\r\nconst ProductGrid = ({ products, favorites, onToggleFavorite }) => {\r\n  const count = Array.isArray(products) ? products.length : 0;\r\n  return (\r\n    <div className=\"flex flex-col mb-[50px] gap-[25px]\">\r\n      <p>Hiện có {count} sản phẩm</p>\r\n      <div className=\" min-w-[1030px] grid grid-cols-4 gap-[30px]\">\r\n        {products?.map((item, index) => (\r\n          <ProductCard\r\n            key={index}\r\n            item={item}\r\n            isFavorite={favorites?.includes(item.product_id)}\r\n            onToggleFavorite={() => onToggleFavorite?.(item.product_id)}\r\n          />\r\n        ))}\r\n      </div>\r\n    </div>\r\n  );\r\n};\r\n\r\nexport default ProductGrid;\r\n\r\n"],"names":[],"mappings":";;;;;AACA;AACA;AAFA;;;;AAIA,MAAM,cAAc,CAAC,EAAE,QAAQ,EAAE,SAAS,EAAE,gBAAgB,EAAE;IAC5D,MAAM,QAAQ,MAAM,OAAO,CAAC,YAAY,SAAS,MAAM,GAAG;IAC1D,qBACE,8OAAC;QAAI,WAAU;;0BACb,8OAAC;;oBAAE;oBAAS;oBAAM;;;;;;;0BAClB,8OAAC;gBAAI,WAAU;0BACZ,UAAU,IAAI,CAAC,MAAM,sBACpB,8OAAC,+JAAW;wBAEV,MAAM;wBACN,YAAY,WAAW,SAAS,KAAK,UAAU;wBAC/C,kBAAkB,IAAM,mBAAmB,KAAK,UAAU;uBAHrD;;;;;;;;;;;;;;;;AASjB;uCAEe","debugId":null}},
    {"offset": {"line": 612, "column": 0}, "map": {"version":3,"sources":["file:///D:/doanchuyennganha/client/src/app/%28user%29/bracelet/page.js"],"sourcesContent":["\"use client\";\r\nimport React from \"react\";\r\nimport Filters from \"../components/Filters\";\r\nimport ProductGrid from \"../components/ProductGrid\";\r\nimport { toIntegerVND } from \"../utils/price\";\r\nimport { useProducts } from \"../../../store/productsStore.jsx\";\r\n\r\nconst parsePrice = toIntegerVND;\r\n\r\nexport default function Page() {\r\n  const { products, status, error, fetchProducts } = useProducts();\r\n  const [favorites, setFavorites] = React.useState([]);\r\n\r\n  React.useEffect(() => {\r\n    if (status === \"idle\") {\r\n      fetchProducts();\r\n    }\r\n  }, [status, fetchProducts]);\r\n\r\n  const [priceRange, setPriceRange] = React.useState(\"\");\r\n  const [color, setColor] = React.useState(\"\");\r\n  const [material, setMaterial] = React.useState(\"\");\r\n  const [sortBy, setSortBy] = React.useState(\"\");\r\n\r\n  const displayedData = React.useMemo(() => {\r\n    let list = Array.isArray(products) ? [...products] : [];\r\n\r\n    // category filter for \"vong tay\"\r\n    list = list.filter((item) => {\r\n      const cat = item?.Category?.name || \"\";\r\n      return String(cat).trim().toLowerCase() === \"vong tay\";\r\n    });\r\n\r\n    if (priceRange) {\r\n      let min = 0, max = Infinity;\r\n      if (priceRange.includes(\"-\")) {\r\n        const [minStr, maxStr] = priceRange.split(\"-\");\r\n        min = Number(minStr);\r\n        max = Number(maxStr);\r\n      } else {\r\n        if (priceRange === \"1\") {\r\n          min = 0;\r\n          max = 20;\r\n        } else if (priceRange === \"2\") {\r\n          min = 20;\r\n          max = 30;\r\n        } else if (priceRange === \"3\") {\r\n          min = 30;\r\n          max = 40;\r\n        } else if (priceRange === \"4\") {\r\n          min = 40;\r\n          max = 100;\r\n        }\r\n      }\r\n      list = list.filter((item) => {\r\n        const price = parsePrice(item.price);\r\n        return price >= min * 1_000_000 && price <= max * 1_000_000;\r\n      });\r\n    }\r\n\r\n    if (color) {\r\n      let colorName = color;\r\n      if (color === \"5\") colorName = \"Vang\";\r\n      else if (color === \"6\") colorName = \"Vang hong\";\r\n      else if (color === \"7\") colorName = \"Trang\";\r\n      list = list.filter(\r\n        (item) => String(item.color).toLowerCase() === String(colorName).toLowerCase()\r\n      );\r\n    }\r\n\r\n    if (material) {\r\n      let materialName = material;\r\n      if (material === \"8\") materialName = \"vang\";\r\n      else if (material === \"9\") materialName = \"kim cuong\";\r\n      list = list.filter(\r\n        (item) => String(item.material).toLowerCase() === String(materialName).toLowerCase()\r\n      );\r\n    }\r\n\r\n    if (sortBy === \"priceAsc\") {\r\n      list.sort((a, b) => parsePrice(a.price) - parsePrice(b.price));\r\n    } else if (sortBy === \"priceDesc\") {\r\n      list.sort((a, b) => parsePrice(b.price) - parsePrice(a.price));\r\n    } else if (sortBy === \"nameAsc\") {\r\n      list.sort((a, b) => a.name.localeCompare(b.name));\r\n    }\r\n\r\n    return list;\r\n  }, [products, priceRange, color, material, sortBy]);\r\n\r\n  const toggleFavorite = (productId) => {\r\n    setFavorites((prev) =>\r\n      prev.includes(productId)\r\n        ? prev.filter((id) => id !== productId)\r\n        : [...prev, productId]\r\n    );\r\n  };\r\n\r\n  return (\r\n    <div className=\" flex flex-col items-center gap-[30px] mt-[40px]\">\r\n      <div className=\" w-[90%]\">\r\n        <p className=\" text-[32px] text-[#9B8D6F] text-left\">Vòng tay</p>\r\n      </div>\r\n      <div className=\"w-[90%] flex flex-row gap-[50px]\">\r\n        <Filters\r\n          priceRange={priceRange}\r\n          color={color}\r\n          material={material}\r\n          sortBy={sortBy}\r\n          onPriceRangeChange={setPriceRange}\r\n          onColorChange={setColor}\r\n          onMaterialChange={setMaterial}\r\n          onSortChange={setSortBy}\r\n        />\r\n\r\n        <div className=\"flex-1\">\r\n          {status === \"loading\" && (\r\n            <div className=\"p-4 text-sm text-gray-500\">Đang tải sản phẩm…</div>\r\n          )}\r\n          {status === \"failed\" && (\r\n            <div className=\"p-4 text-sm text-red-500\">Lỗi tải dữ liệu: {String(error)}</div>\r\n          )}\r\n          <ProductGrid\r\n            products={displayedData}\r\n            favorites={favorites}\r\n            onToggleFavorite={toggleFavorite}\r\n          />\r\n        </div>\r\n      </div>\r\n    </div>\r\n  );\r\n}\r\n\r\n"],"names":[],"mappings":";;;;;AACA;AACA;AACA;AACA;AACA;AALA;;;;;;;AAOA,MAAM,aAAa,wJAAY;AAEhB,SAAS;IACtB,MAAM,EAAE,QAAQ,EAAE,MAAM,EAAE,KAAK,EAAE,aAAa,EAAE,GAAG,IAAA,6IAAW;IAC9D,MAAM,CAAC,WAAW,aAAa,GAAG,gNAAK,CAAC,QAAQ,CAAC,EAAE;IAEnD,gNAAK,CAAC,SAAS,CAAC;QACd,IAAI,WAAW,QAAQ;YACrB;QACF;IACF,GAAG;QAAC;QAAQ;KAAc;IAE1B,MAAM,CAAC,YAAY,cAAc,GAAG,gNAAK,CAAC,QAAQ,CAAC;IACnD,MAAM,CAAC,OAAO,SAAS,GAAG,gNAAK,CAAC,QAAQ,CAAC;IACzC,MAAM,CAAC,UAAU,YAAY,GAAG,gNAAK,CAAC,QAAQ,CAAC;IAC/C,MAAM,CAAC,QAAQ,UAAU,GAAG,gNAAK,CAAC,QAAQ,CAAC;IAE3C,MAAM,gBAAgB,gNAAK,CAAC,OAAO,CAAC;QAClC,IAAI,OAAO,MAAM,OAAO,CAAC,YAAY;eAAI;SAAS,GAAG,EAAE;QAEvD,iCAAiC;QACjC,OAAO,KAAK,MAAM,CAAC,CAAC;YAClB,MAAM,MAAM,MAAM,UAAU,QAAQ;YACpC,OAAO,OAAO,KAAK,IAAI,GAAG,WAAW,OAAO;QAC9C;QAEA,IAAI,YAAY;YACd,IAAI,MAAM,GAAG,MAAM;YACnB,IAAI,WAAW,QAAQ,CAAC,MAAM;gBAC5B,MAAM,CAAC,QAAQ,OAAO,GAAG,WAAW,KAAK,CAAC;gBAC1C,MAAM,OAAO;gBACb,MAAM,OAAO;YACf,OAAO;gBACL,IAAI,eAAe,KAAK;oBACtB,MAAM;oBACN,MAAM;gBACR,OAAO,IAAI,eAAe,KAAK;oBAC7B,MAAM;oBACN,MAAM;gBACR,OAAO,IAAI,eAAe,KAAK;oBAC7B,MAAM;oBACN,MAAM;gBACR,OAAO,IAAI,eAAe,KAAK;oBAC7B,MAAM;oBACN,MAAM;gBACR;YACF;YACA,OAAO,KAAK,MAAM,CAAC,CAAC;gBAClB,MAAM,QAAQ,WAAW,KAAK,KAAK;gBACnC,OAAO,SAAS,MAAM,aAAa,SAAS,MAAM;YACpD;QACF;QAEA,IAAI,OAAO;YACT,IAAI,YAAY;YAChB,IAAI,UAAU,KAAK,YAAY;iBAC1B,IAAI,UAAU,KAAK,YAAY;iBAC/B,IAAI,UAAU,KAAK,YAAY;YACpC,OAAO,KAAK,MAAM,CAChB,CAAC,OAAS,OAAO,KAAK,KAAK,EAAE,WAAW,OAAO,OAAO,WAAW,WAAW;QAEhF;QAEA,IAAI,UAAU;YACZ,IAAI,eAAe;YACnB,IAAI,aAAa,KAAK,eAAe;iBAChC,IAAI,aAAa,KAAK,eAAe;YAC1C,OAAO,KAAK,MAAM,CAChB,CAAC,OAAS,OAAO,KAAK,QAAQ,EAAE,WAAW,OAAO,OAAO,cAAc,WAAW;QAEtF;QAEA,IAAI,WAAW,YAAY;YACzB,KAAK,IAAI,CAAC,CAAC,GAAG,IAAM,WAAW,EAAE,KAAK,IAAI,WAAW,EAAE,KAAK;QAC9D,OAAO,IAAI,WAAW,aAAa;YACjC,KAAK,IAAI,CAAC,CAAC,GAAG,IAAM,WAAW,EAAE,KAAK,IAAI,WAAW,EAAE,KAAK;QAC9D,OAAO,IAAI,WAAW,WAAW;YAC/B,KAAK,IAAI,CAAC,CAAC,GAAG,IAAM,EAAE,IAAI,CAAC,aAAa,CAAC,EAAE,IAAI;QACjD;QAEA,OAAO;IACT,GAAG;QAAC;QAAU;QAAY;QAAO;QAAU;KAAO;IAElD,MAAM,iBAAiB,CAAC;QACtB,aAAa,CAAC,OACZ,KAAK,QAAQ,CAAC,aACV,KAAK,MAAM,CAAC,CAAC,KAAO,OAAO,aAC3B;mBAAI;gBAAM;aAAU;IAE5B;IAEA,qBACE,8OAAC;QAAI,WAAU;;0BACb,8OAAC;gBAAI,WAAU;0BACb,cAAA,8OAAC;oBAAE,WAAU;8BAAwC;;;;;;;;;;;0BAEvD,8OAAC;gBAAI,WAAU;;kCACb,8OAAC,2JAAO;wBACN,YAAY;wBACZ,OAAO;wBACP,UAAU;wBACV,QAAQ;wBACR,oBAAoB;wBACpB,eAAe;wBACf,kBAAkB;wBAClB,cAAc;;;;;;kCAGhB,8OAAC;wBAAI,WAAU;;4BACZ,WAAW,2BACV,8OAAC;gCAAI,WAAU;0CAA4B;;;;;;4BAE5C,WAAW,0BACV,8OAAC;gCAAI,WAAU;;oCAA2B;oCAAkB,OAAO;;;;;;;0CAErE,8OAAC,+JAAW;gCACV,UAAU;gCACV,WAAW;gCACX,kBAAkB;;;;;;;;;;;;;;;;;;;;;;;;AAM9B","debugId":null}},
